  PanelText_UI_Events_2ndAnnivWB_StageGroup_Text_C_Introduction_Content = {
    Text = [[
Ayo, dengan kegilaan, pembunuhan, dan penderitaan sebagai nada, nyanyikanlah Requiem yang berkilau di antara bintang-bintang. 
Eksistensi tertinggi yang bodoh dan kacau ini tidak seharusnya terbangun, baik saat ini maupun di masa depan.]]
  },
