  },
  PanelText_UI_Events_Activity_StageGroup_Text_C_Introduction_Content = {
    Text = [[
Janji Dewa semakin mendekat.
Menunggu ribuan tahun akan segera menyambut akhir yang penuh sukacita, tempat yang dijanjikan akan muncul dari dalam laut.
Dewa akan dibangkitkan dari rongga dada Sang Dewi, pada akhir tujuh hari, dunia baru akan datang.]]
  },
