  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Introduction_Content = {
    Text = [[
Lampu menyala. Tepuk tangan mereda. Para penonton menanti.
Saatnya naik ke panggung, anak-anakku yang tersayang. Pergilah ke atas panggung, tampilkan pertunjukan, robek isi hatimu, dan jual rahasia terdalammu. Jadikan luka-lukamu yang paling pedih sebagai hidangan penutup untuk menghibur orang lain. Nikmatilah dengan rakus cahaya panggung yang hanya menyala untukmu, hingga tirai mengubur dirimu bersama para penonton.
Ini adalah panggung yang ditakdirkan untukmu, naiklah! Jangan takut, tak perlu gentar.]]
  },
