  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Introduction_Content = {
    Text = "♪~~♫~~♪~~♫~~♪~~♫~~\nDi bawah gunung bersalju, semua pemandu mengingatnya, semua anak-anak menyanyikannya. Itulah perwujudan kehendak gunung salju yang megah, itulah dewi penyayang Umapati.\nKekuatan ilahiahnya tersebar di dunia manusia, harta-hartanya tak dapat ditemukan, mereka begitu dekat, namun tak meninggalkan jejak. Relakanlah sesuatu, pertahankanlah sesuatu.\nMereka yang tidak tulus kepada wujud sejati sang dewi, akan terkubur selamanya bersama gunung salju yang telah mati."
  },
