  },
  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "Seumur hidup burung, ditakdirkan untuk hidup bebas. Kamu seharusnya melihat saat ia memecahkan cangkangnya, ia merebut kembali kebebasan hidup dari tangan kematian. Kamu seharusnya melihat saat ia belajar terbang, ia merebut kembali kebebasan untuk hidup sendiri dari sarang yang nyaman. Jika sekarang kunci kebebasan dilemparkan ke dalam jurang kematian, maka ia pasti akan melompat tanpa ragu-ragu, memilih untuk menghadapi badai kematian di antara kehidupan yang sempit dan kebebasan yang tak terbatas."
  },
