  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = "Di kota kecil tepi laut ini, terdapat jalan komersial yang ramai. Perdagangan laut telah mengumpulkan banyak barang baru di sini, asalkan Anda membayar cukup Léofang, Anda pasti akan mendapatkan barang yang memuaskan. \n Hanya ada satu toko kecil di sudut jalan, yaitu sebuah toko yang penuh dengan barang antik ajaib, di antara asap yang dihembuskan dari pipa, pemilik wanita yang mengenakan topi lebar akan perlahan-lahan menunjukkan senyuman kepada Anda. \n \"Selamat datang di Toko Kecil Penawar Kebingungan, di sini dapat memenuhi semua kebutuhan Anda, asalkan Anda membayar imbalan yang cukup...\" \n \"Tentu saja, tentu saja, harganya wajar, tidak ada penipuan untuk anak-anak maupun orang tua.\""
  },
