  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = [[
Dia sekali lagi berdiri di atas Bumi, balas dendam yang memusnahkan segalanya pun datang tepat pada waktunya.

Itu adalah pengejaran yang tak pernah berhenti, itu adalah api membara dari Pemilik Ledakan Api.

Dia akan melangkah melalui setiap sudut, memburu semua yang telah menandatangani kontrak dengan Sang Maut.

Larilah, larilah, larilah ke dalam kegelapan yang lebih dalam, larilah ke tempat yang kau kira tak akan ditemukan.

Meskipun ini tidak ada artinya, karena Dia pada akhirnya akan melintasi setiap dunia.

Dia akan memburu semua hingga segalanya menjadi abu.]]
  },
