  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = [[
Suatu hari, kamu tiba-tiba menyadari bahwa dirimu telah berubah. 
 Tidak ada yang menyadari hal ini, karena kamu memiliki perilaku dan penampilan yang sama. 
 Namun, kamu sangat menyadari bahwa hati yang dulunya merah cerah itu, kini tertutup oleh sebuah topeng yang terbuat dari kabut. 
"Jika aku bisa terus berpura-pura, apakah aku masih menjadi diriku yang sebelumnya?"
 Selamat, pertanyaan ini tidak tinggal lebih dari satu detik di dalam otakmu, karena sebelum topeng itu terungkap, tidak ada yang tahu pemikiran aslimu. 
"Mari kita berangkat dulu~"]]
  },
